class Solution {
public:
    long long wonderfulSubstrings(string word) {
        long long count[1024] = {0};
        count[0] = 1;
        int mask = 0;
        long long ans = 0;
        for (char c : word) {
            mask ^= (1 << (c - 'a'));
            ans += count[mask];
            for (int k = 0; k < 10; k++) {
                ans += count[mask ^ (1 << k)];
            }
            count[mask]++;
        }
        return ans;
    }
};
